"""Smali of the Java helpers in helpers/java, generated by helpers/build.py (committed, so patching
needs no Android SDK).  A patch adds the classes it calls with add_helpers()."""
from __future__ import annotations

import re
from importlib import resources

from ..smali import SmaliTree, class_descriptor


def smali(name: str) -> str:
    """The smali of one generated file, e.g. smali("Mic$1")."""
    return resources.files(__name__).joinpath(f"{name}.smali").read_text(encoding="utf-8")


def add_helpers(tree: SmaliTree, *classes: str) -> list[str]:
    """Add each helper class with its inner classes (Mic -> Mic, Mic$1, Mic$2); returns the descriptors."""
    names = sorted(p.name[:-len(".smali")] for p in resources.files(__name__).iterdir() if p.name.endswith(".smali"))
    added = []
    for cls in classes:
        group = [n for n in names if re.fullmatch(re.escape(cls) + r"(\$.+)?", n)]
        if cls not in group:
            raise FileNotFoundError(f"no generated helper {cls}.smali -- run helpers/build.py")
        for n in group:
            text = smali(n)
            tree.add_class(class_descriptor(text), text)
            added.append(class_descriptor(text))
    return added
